import channels_graphql_ws
import graphene
from graphql import GraphQLError
from .models import Device, TelemetryReading
from .types import TelemetryType

class DeviceTelemetrySubscription(channels_graphql_ws.Subscription):
    telemetry = graphene.Field(TelemetryType)

    class Arguments:
        device_id = graphene.String(required=True)

    @classmethod
    def subscribe(cls, root, info, device_id):
        user = info.context.user
        if not user.is_authenticated:
            raise GraphQLError("Authentication required")

        if not Device.objects.filter(id=device_id, facility__organization=user.organization).exists():
            raise GraphQLError("Device not found or access denied")

        group_name = f"telemetry_stream_{device_id}"
        return [group_name]

    @classmethod
    def publish(cls, payload, info, device_id):
        return cls(telemetry=payload["telemetry_reading"])
